export function mergeCommunityOffers(products){
 const incoming=new Map(communityProducts.map(p=>[p.id,p]));
 const out=products.map(p=>{const q=incoming.get(p.id);incoming.delete(p.id);if(!q||p.communitySource||!p.enquiryOnly||p.price!==null)return p;return {...p,...structuredClone(q),image:p.image,photoPending:false,...(p.notePyramid?Object.fromEntries(['notePyramid','notes','description','finderVerified','family','scentEdit','pairing','concentration','noteSources','notesQuality','factsCheckedAt','factsRevision','publishedSizes'].filter(k=>p[k]!==undefined).map(k=>[k,p[k]])):{}),hidden:p.hidden,archived:p.archived,order:p.order,featureOrder:p.featureOrder};});
 return [...out,...structuredClone([...incoming.values()])];
}
export function communityQuoteLabel(p){const q=p.communityOffer;return q?('Community quote · '+q.postedAt+(q.pricePlus?' · + charges to confirm':'')):'';}
